def RawDegreeHomologyBounded (X : Type*) [TopologicalSpace X] (bound : ℕ) : Prop :=
  (∀ n, FiniteDimensional ℚ (RawDegreeHomology X n)) ∧
    ∀ n, bound ≤ n → Subsingleton (RawDegreeHomology X n)

